// Cloudflare's bundler can't import a .csv file, so before every dev run and deploy this copies
// concrete_evidence/reference/cities.csv (the one list Python and the app share) into lib/cities.gen.js.
// The generated file is not in git; edit the CSV, never the copy.
import { readFileSync, writeFileSync } from "node:fs";

const src = new URL("../../concrete_evidence/reference/cities.csv", import.meta.url);
const out = new URL("../lib/cities.gen.js", import.meta.url);
writeFileSync(out, `// Generated by scripts/cities.mjs from concrete_evidence/reference/cities.csv. Do not edit.\nexport default ${JSON.stringify(readFileSync(src, "utf8"))};\n`);
